VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-taiia','Taiia Divine Stat Block','203-205',
 'Taiia is the divine-rank-20 greater deity of the monotheistic Faith of the Sun, simultaneously Creator and Destroyer.',
 '{"deitySlug":"taiia","religion":"faith-of-the-sun","sourceEdition":"3.0","rankBand":"greater","divineRank":20,"titles":["The Watcher","The Maker","The Devourer","The Dancer","The Blinding Light"],"symbol":"Solar disk with three eyes","homePlane":null,"homePlaneSourceNote":"The deity identity block does not print a Home Plane line; none is invented.","alignment":"N","classes":[{"class":"Barbarian","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","size":"Huge","hitDice":"20d8+340 outsider + 20d12+340 barbarian + 20d8+340 cleric","hitPoints":1580,"initiative":9,"speed":{"land":110},"armorClass":{"total":78,"size":-2,"dexterity":9,"divine":20,"natural":33,"deflection":8},"printedFace":"5 ft. by 10 ft.","printedReachFeet":15},"attacks":{"longsword":"Huge +5 brilliant energy longsword +76/+71/+66/+61 melee","speedFlail":"Huge +5 speed light flail +76/+71/+66/+61 melee","holyTrident":"Huge +5 holy trident +76/+71/+66/+61 melee","unholyBattleaxe":"Huge +5 unholy battleaxe +76/+71/+66/+61 melee","spellTouch":{"melee":72,"ranged":65},"greaterDeityAlways20OnAttacks":true},"damage":{"longsword":"2d8+21/19-20; greater deity maximum 37","speedFlail":"2d8+13; greater deity maximum 29","holyTrident":"2d8+13; greater deity maximum 29","unholyBattleaxe":"2d8+13/x3; greater deity maximum 29","greaterDeityMaximumDamage":true},"specialAttacks":{"turnOrRebukeUndeadPerDay":11},"specialQualities":{"divineImmunities":true,"fireImmunity":true,"printedDamageReduction":"55/+4 (4/-)","fastHealing":40,"spontaneousDivineCasting":true,"languages":"understand, speak, and read all languages; communicate directly with all beings within 20 miles","remoteCommunication":true,"godlyRealm":true,"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true,"fastMovement":true,"greaterRageUsesPerDay":6,"uncannyDodge":"cannot be flanked, +4 against traps","spellResistance":52,"divineAura":{"radiusMiles":20,"dc":37}},"saves":{"fort":69,"ref":61,"will":60,"greaterDeityAlways20":true},"abilities":{"str":43,"dex":28,"con":45,"int":29,"wis":26,"cha":27},"skills":{"Climb":76,"Concentration":77,"Diplomacy":68,"Heal":68,"Hide":21,"Innuendo":68,"Intimidate":68,"Intuit Direction":68,"Jump":76,"Knowledge (arcana)":69,"Knowledge (geography)":49,"Knowledge (history)":69,"Knowledge (religion)":79,"Listen":70,"Ride (horse)":49,"Scry":69,"Spellcraft":69,"Spot":70,"Swim":76,"Wilderness Lore":68},"feats":["Alertness","Cleave","Dodge","Expertise","Great Cleave","Greater Multiweapon Fighting","Improved Bull Rush","Improved Multiweapon Fighting","Mobility","Multidexterity","Multiweapon Fighting","Power Attack","Spring Attack","Sunder","Superior Expertise","Weapon Focus (longsword)","Weapon Focus (light flail)","Weapon Focus (trident)","Weapon Focus (battleaxe)","Whirlwind Attack"],"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Annihilating Strike","Create Greater Object","Create Object","Divine Celerity","Divine Creation","Divine Fast Healing","Divine Rage","Energy Storm (any energy form)","Extra Domain (Destruction)","Extra Domain (Healing)","Extra Domain (Strength)","Extra Domain (Travel)","Extra Domain (War)","Extra Energy Immunity (fire)","Gift of Life","Hand of Death","Life and Death","Mass Life and Death","Rejuvenation","Shapechange","True Shapechange"],"domainAccess":{"creator":{"domains":["Air","Chaos","Earth","Good","Healing","Knowledge","Law","Luck","Magic","Protection","Sun","Travel"],"favoredWeapon":"trident"},"destroyer":{"domains":["Chaos","Death","Destruction","Evil","Fire","Law","Strength","Trickery","War","Water"],"favoredWeapon":"battleaxe"}},"domainPowers":{"deathTouch":{"usesPerDay":20,"thresholdHitPoints":120},"destructionSmite":{"usesPerDay":20,"attackBonus":4,"damageBonus":20},"healingSpellsCasterLevelBonus":1,"protectiveWard":{"usesPerDay":20,"resistanceBonus":20,"maximumDuration":"1 hour"},"strengthFeat":{"usesPerDay":20,"strengthEnhancementBonus":20,"durationRounds":1},"greaterTurningUsesPerDay":20,"freedomOfMovementRoundsPerDay":20},"spellLikeAbilities":{"sourceNote":"Taiia grants twenty domains to clerics but personally uses spell-like abilities from only eight domains: Death, Destruction, Healing, Protection, Strength, Sun, Travel, and War.","domainsUsed":["Death","Destruction","Healing","Protection","Strength","Sun","Travel","War"],"casterLevel":30,"healingCasterLevel":31,"saveDc":"38 + spell level"},"divineRagePrinted":{"labelInBlock":"Greater Rage","usesPerDay":6,"armorClass":76,"hitPoints":1760,"attack":"+79/+74/+69/+64 melee","damageBonus":3,"fort":72,"will":63,"str":52,"con":51,"climb":79,"jump":79,"swim":79,"durationRounds":23,"notWindedAfterward":true,"sourceInterpretation":"The stat block labels the class-derived raging state Greater Rage, while Taiia also possesses the Divine Rage salient ability. Preserve both source facts; revised Divine Rage supersedes ordinary rage action-economy behavior when invoked."},"spellcasting":{"clericSpellsPerDay":"6/8/8/8/8/7/6/6/6/5","clericBaseDc":"18 + spell level"},"greaterDeityTraits":{"automaticBestPossibleDieResult":true,"immortal":true},"senses":{"normalRangeMiles":20,"remoteSenseAnchors":["any animal","worshipers","holy sites","objects","locations where a title or name was spoken in the last hour"],"maximumRemoteLocations":20,"sensingBlockLocations":2,"sensingBlockHours":20},"portfolioSense":"All acts of creation, births, and deaths twenty weeks before they occur and twenty weeks after they occur.","automaticActions":{"skills":"any skill, including untrained skills","freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any magic item.","avatarStatus":"Taiia does not possess the Avatar salient divine ability; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":[],"damageReduction":"30/epic","barbarianDamageReduction":"5/-","fireImmunityFromSalientAbility":true,"ordinaryRankFireResistanceWouldBe":25,"additionalOutsiderSkillPoints":51,"additionalFeat":1,"spaceReach":"Use revised Huge humanoid space/reach (15 ft./15 ft.) instead of the printed 3.0 Face 5x10/reach 15 when executing revised combat.","barbarian":{"trapSenseIncrease":2,"classDamageReduction":"5/- instead of 4/-","mightyRageNote":"Divine Rage replaces ordinary mighty rage when the salient ability is used.","indomitableWillBonusAgainstEnchantmentWhileRaging":4},"cleric":"No class-feature change in the official revision.","divineCelerity":"Functions according to revised haste.","divineRage":"Instead of an extra partial action, grants one extra attack at full attack bonus whenever Taiia takes a full attack action.","domainSpellChanges":["Destruction: circle of doom -> mass inflict light wounds","Healing: healing circle -> mass cure light wounds","Strength: endure elements -> enlarge person","Travel: expeditious retreat -> longstrider; teleport without error -> greater teleport","use revised spell names/effects throughout all eight SLA domains"],"skills":{"defunct":["Innuendo","Scry"],"migrations":["Intuit Direction -> Survival/navigation functions","Wilderness Lore -> Survival"]},"feats":{"extraOutsiderFeat":1,"multidexterity":"Multidexterity is obsolete in revised rules; rebuild the multiweapon chain with current Multiweapon Fighting rules rather than treating it as a live 3.5 feat.","expertise":"Use Combat Expertise as the revised feat name.","sunder":"Use revised Improved Sunder where the old Sunder feat maps to it."}}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
       'Use the structured mechanics payload for Taiia. Printed 3.0 values remain source-of-truth; revision3_5 records official revised-game deltas and does not erase source contradictions.',
       0,NULL,1,'deity','divine-stat-block',0,1,'dd-faith-of-the-sun',NULL,
       '["deities-and-demigods","other-religions","taiia","deity-stat-block","revision-3.5"]',d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);